/**
 * The Chart of Accounts exactly as specified in Annexure D to the SRS
 * ("EK Group - Bakery ERP - Annexure D - Chart of Accounts and Accounting
 * Schema v1.0"), converted from its seed_coa.sql without alteration.
 *
 * THIS FILE IS DATA, NOT CODE. It is the account master the finance team signed
 * off; do not edit an account here to fix a symptom elsewhere. If the annexure
 * is revised, re-convert rather than hand-patch, so the two cannot drift.
 *
 * Counts as shipped by the annexure's own verification (D.16): 44 groups,
 * 253 ledger accounts, 635 company adoptions, 8 cost-centre categories.
 * Now 246 accounts and 621 adoptions — see coa-revisions.ts for what the finance
 * team has changed since, and why the two no longer agree.
 */

import {
  AccountNature,
  BalanceSide,
  PartyKind,
  StatementType,
} from '@prisma/client';

/**
 * The annexure's cost-centre rule per account (D.5). It lives here rather than
 * in the schema because it is a fact about the annexure, not a column: what the
 * entry screen asks for is Account.hasCostCenter / hasCostObject, which the
 * seed derives from this.
 */
export type CcRequirement = 'MANDATORY' | 'OPTIONAL' | 'NOT_APPLICABLE';

/** The annexure's company codes, mapped to this ERP's companies by code. */
export const COA_COMPANY_BY_CODE: Record<string, string> = {
  // Edakkattukudiyil Regency Food Products Private Limited
  MFG: 'EK001',
  // Regency Bakers & Confectionaries
  TRD: 'EK003',
  // Edakkattukudiyil Regency Bake House Private Limited
  RTL: 'EK002',
};

export interface CoaGroup {
  code: string;
  name: string;
  parentCode: string | null;
  nature: AccountNature;
  normalSide: BalanceSide;
  statement: StatementType;
  tallyGroup: string | null;
  sortOrder: number;
  /** Omitted = in use. Set false for a block the group does not post to. */
  isActive?: boolean;
}

export interface CoaAccount {
  code: string;
  name: string;
  groupCode: string;
  nature: AccountNature;
  normalSide: BalanceSide;
  statement: StatementType;
  tallyGroup: string | null;
  isContra: boolean;
  isControl: boolean;
  controlParty: PartyKind | null;
  ccRequirement: CcRequirement;
  isGstRelevant: boolean;
  isBankOrCash: boolean;
  isReconcilable: boolean;
  isIntercompany: boolean;
  eliminationPair: string | null;
  allowManualJe: boolean;
  isSystem: boolean;
  notes: string | null;
  sortOrder: number;
  /**
   * Omitted = in use. Set false for an account the group's method never posts
   * to: the purchase block, where a receipt debits inventory and the cost
   * reaches the profit and loss on consumption instead. Kept in the master
   * rather than withdrawn, so the numbering stays whole and the decision can be
   * read — and reversed — where it was made.
   */
  isActive?: boolean;
}

export interface CoaCostCentreCategory {
  code: string;
  name: string;
  description: string | null;
  isMandatory: boolean;
}

